using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Non-throwing probe with TryGetTypeInfo
//    Case A: type IS resolvable
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    Console.WriteLine($"Probe succeeded for Person: {found!.Type.Name}");
}

// Case B: use a resolver that only handles Person, so probing for int[] will fail
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty – resolves nothing
};

if (limited.TryGetTypeInfo(typeof(int[]), out _))
{
    Console.WriteLine("Probe succeeded for int[] (unexpected)");
}
else
{
    Console.WriteLine("Probe returned false for int[] — no metadata available, no exception thrown");
}

// Simple model
public record Person(string Name, int Age);

